<?php
$header=is_array($document['header']??null)?$document['header']:[];
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$sections=[
 'total_sales'=>'TOTAL SALES','counter_sales'=>'COUNTER SALES','cashier_collections'=>'CASHIER COLLECTIONS',
 'customer_credit_bills'=>'CUSTOMER CREDIT BILLS','customer_credit_payments'=>'CUSTOMER CREDIT PAYMENTS','waiter_totals'=>'WAITER TOTALS'
];
?><!doctype html><html><head><meta charset="utf-8"><title>SSP</title><style>@page{size:80mm auto;margin:0}*{box-sizing:border-box}body{width:79mm;margin:0;font:10px Arial;color:#000}.ssp{padding:2mm}.center{text-align:center}.stars{white-space:nowrap;overflow:hidden;font-weight:bold}h1{font-size:17px;margin:2px 0}h2{font-size:12px;border-bottom:1px solid #000;margin:6px 0 2px;padding-bottom:2px}table{width:100%;border-collapse:collapse}td,th{padding:2px 1px;text-align:left;border-bottom:1px dotted #777}td:not(:first-child),th:not(:first-child){text-align:right}.meta{display:flex;justify-content:space-between}.empty{text-align:center;padding:3px}</style></head><body><main class="ssp"><header class="center"><div class="stars">***********************************************************</div><h1><?= $esc($header['company_name']??'') ?></h1><b><?= $esc($header['shift']??$header['shift_date']??'') ?> SHIFT SUMMARY PRINT</b><div><?= $esc($header['cashier_name']??$header['user']??$header['served_by']??'') ?></div><div><?= $esc($header['print_time']??'') ?></div><div class="stars">***********************************************************</div></header><?php foreach($sections as $key=>$label): $rows=$document[$key]??[]; if(is_array($rows)&&!array_is_list($rows))$rows=[$rows]; ?><section><h2><?= $esc($label) ?></h2><?php if(!$rows): ?><div class="empty">No records</div><?php else: ?><table><?php foreach($rows as $row): $row=is_array($row)?$row:['value'=>$row]; $values=array_values($row); ?><tr><?php foreach($values as $value): ?><td><?= $esc(is_scalar($value)?$value:json_encode($value)) ?></td><?php endforeach; ?></tr><?php endforeach; ?></table><?php endif; ?></section><?php endforeach; ?><footer class="center"><div class="stars">***********************************************************</div>END OF SHIFT SUMMARY</footer></main></body></html>
